const { execSync } = require('child_process');
const dir = $json.directory || '/data/workspace';
const result = execSync(`node /data/tools/fs/list_dir.js ${dir}`).toString();
return JSON.parse(result);

const { execSync } = require('child_process');
const filename = $json.filename;
const result = execSync(`node /data/tools/fs/read_file.js /data/workspace/${filename}`).toString();
return JSON.parse(result);

const { execSync } = require('child_process');
const filename = $json.filename;
const base64Content = $json.content_base64;
const result = execSync(`node /data/tools/fs/write_file.js /data/workspace/${filename} "${base64Content}" overwrite`).toString();
return JSON.parse(result);

const { execSync } = require('child_process');
const message = $json.message || 'update';
const result = execSync(`node /data/tools/git/commit.js "${message}"`).toString();
return { result: result.trim() };
